CREATE OR REPLACE FUNCTION private.apply_payroll_custom_money()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  settings jsonb := '{}'::jsonb;
  tax_result jsonb;
  custom_earnings_total integer := 0;
  custom_deductions_total integer := 0;
  previous_earnings_total integer := 0;
  fixed_deductions_total integer := 0;
  normalized_earnings jsonb := '[]'::jsonb;
  normalized_deductions jsonb := '[]'::jsonb;
  item jsonb;
  item_name text;
  item_amount integer;
  payment_day integer := 25;
begin
  if not new.automatic_calculation or new.workflow_state <> 'draft' then
    return new;
  end if;

  perform pg_advisory_xact_lock_shared(hashtextextended(new.company_id::text||':payroll-rate-registry',0));

  select coalesce(to_jsonb(s),'{}'::jsonb)
  into settings
  from public.worker_payroll_settings s
  where s.company_id=new.company_id
    and s.worker_id=new.worker_id;

  settings:=payroll_unit_private.augment_settings(new.company_id,new.worker_id,new.period_start,new.period_end,settings);
  if coalesce((settings#>>'{_unit_resolution,blocked}')::boolean,false) then new.calculation_blocked:=true;end if;
  -- Company policy is the only source; legacy worker payment_day is ignored.
  select c.payroll_payment_day into payment_day
  from public.companies c where c.id=new.company_id;
  payment_day:=greatest(least(coalesce(payment_day,25),31),1);

  -- Fresh calculator detail does not contain previously applied named earnings.
  -- Only subtract them for an edit carrying the normalized prior detail.
  if tg_op='UPDATE' and coalesce(new.detail,'{}'::jsonb) ? 'custom_earnings_total' then
    previous_earnings_total :=
      coalesce((old.detail->>'custom_earnings_total')::integer,0);
  end if;

  if jsonb_typeof(settings->'custom_earnings')='array' then
    for item in
      select value
      from jsonb_array_elements(settings->'custom_earnings')
    loop
      item_name := nullif(trim(item->>'name'),'');
      item_amount := greatest(coalesce((item->>'amount_yen')::integer,0),0);
      if item_name is null then continue; end if;
      normalized_earnings := normalized_earnings || jsonb_build_array(
        jsonb_build_object('name',item_name,'amount_yen',item_amount)
      );
      custom_earnings_total := custom_earnings_total + item_amount;
    end loop;
  end if;

  if jsonb_typeof(settings->'custom_deductions')='array' then
    for item in
      select value
      from jsonb_array_elements(settings->'custom_deductions')
    loop
      item_name := nullif(trim(item->>'name'),'');
      item_amount := greatest(coalesce((item->>'amount_yen')::integer,0),0);
      if item_name is null then continue; end if;
      normalized_deductions := normalized_deductions || jsonb_build_array(
        jsonb_build_object('name',item_name,'amount_yen',item_amount)
      );
      custom_deductions_total := custom_deductions_total + item_amount;
    end loop;
  end if;

  fixed_deductions_total :=
      round(coalesce((settings->>'income_tax_monthly')::numeric,0))::integer
    + (resident_tax_private.resolve(new.company_id,new.worker_id,new.period_start)->>'amount_yen')::integer
    + round(coalesce((settings->>'social_insurance_monthly')::numeric,0))::integer
    + round(coalesce((settings->>'other_deduction_monthly')::numeric,0))::integer;

  new.gross_pay := greatest(
    coalesce(new.gross_pay,0) - previous_earnings_total + custom_earnings_total,
    0
  );
  new.deductions := greatest(
    fixed_deductions_total + custom_deductions_total,
    0
  );
  new.net_pay := greatest(new.gross_pay - new.deductions,0);
  new.detail := (
    coalesce(new.detail,'{}'::jsonb)
      - '勤続手当'
      - '役職手当'
      - '働き方手当'
      - '介護保険料'
      - '厚生年金保険'
      - '雇用保険料'
      - 'SKB会費'
  ) || jsonb_build_object(
    'resident_tax_source',resident_tax_private.resolve(new.company_id,new.worker_id,new.period_start),
    '家族手当',round(coalesce((settings->>'family_monthly')::numeric,0))::integer,
    'unit_resolution',settings->'_unit_resolution',
    'custom_earnings',normalized_earnings,
    'custom_deductions',normalized_deductions,
    'custom_earnings_total',custom_earnings_total,
    '支払日',payment_day
  );

  tax_result:=payroll_tax_private.calculate(new.company_id,new.worker_id,new.period_start,new.period_end,new.gross_pay,new.deductions);
  if tax_result->>'blocked'='true' then
    new.calculation_blocked:=true;
    new.detail:=new.detail||jsonb_build_object('tax_calculation',tax_result);
  elsif tax_result is not null then
    new.deductions:=(tax_result->>'deductions')::integer;
    new.net_pay:=greatest(new.gross_pay-new.deductions,0);
    new.detail:=new.detail||jsonb_build_object('所得税',(tax_result->>'income_tax_yen')::integer,'tax_calculation',tax_result);
    if tax_result#>>'{conditions,insurance_mode}' IN ('rates','manual') then
      new.detail:=(new.detail-array['社会保険','健康保険料','介護保険料','厚生年金保険','雇用保険料','子ども・子育て支援金'])||(tax_result->'premiums');
    else
      new.detail:=new.detail||jsonb_build_object('社会保険',(tax_result->>'social_yen')::integer);
    end if;
  else
    new.detail:=new.detail-'tax_calculation';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION private.refresh_automatic_payroll_internal(cid uuid, wid uuid, day date)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  start_day date:=date_trunc('month',day)::date;
  end_day date:=(date_trunc('month',day)+interval '1 month - 1 day')::date;
  settings jsonb; resident_source jsonb; a record; current_statement public.payroll_statements%rowtype;
  total numeric:=0; v_deductions numeric:=0; v_custom_deductions numeric:=0; count_rows int:=0;
  category text; allowance text; allowance_index int; seen text[]:='{}'; token text;
  line_detail jsonb; fingerprint text; saved_id uuid; saved_revision int;
  pref record;
  fixed_trade_seen uuid[]:='{}';
  trade_amount numeric;
  expected_gross numeric:=0;
  expected_net numeric:=0;
  tax_result jsonb;
  custom_earnings_total numeric:=0;
  regular_day_base numeric:=0;
  leave_days integer:=0; leave_daily numeric:=0; leave_total numeric:=0;
begin
  perform pg_advisory_xact_lock_shared(hashtextextended(cid::text||':payroll-rate-registry',0));
  perform pg_advisory_xact_lock(hashtextextended(cid::text||wid::text||start_day::text,0));
  select * into current_statement
  from public.payroll_statements
  where company_id=cid and worker_id=wid and period_start=start_day and period_end=end_day
  for update;
  if found and (not current_statement.automatic_calculation or current_statement.workflow_state<>'draft') then return; end if;

  select to_jsonb(s) into settings
  from public.worker_payroll_settings s
  where s.company_id=cid and s.worker_id=wid;

  settings:=payroll_unit_private.augment_settings(cid,wid,start_day,end_day,settings);
  resident_source := resident_tax_private.resolve(cid,wid,start_day);

  select md5(
    'paid_leave_wage_contract:1'||
    case when resident_source->>'mode'='timeline' then
      coalesce((settings-'updated_at'-'payment_day'-'resident_tax_monthly')::text,'')||resident_source::text
      else coalesce((settings-'updated_at'-'payment_day')::text,'') end||
    coalesce((select jsonb_build_object('payment_day',c.payroll_payment_day,
      'payment_month_offset',c.payroll_payment_month_offset,
      'closing_day',c.payroll_closing_day)::text from public.companies c where c.id=cid),'')||
    coalesce((
      select jsonb_agg(to_jsonb(ae)-'updated_at'-'created_at' order by ae.work_date,ae.id)::text
      from public.attendance_entries ae
      where ae.company_id=cid and ae.worker_id=wid
        and ae.work_date between start_day and end_day
        and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date
    ),'')||
    coalesce((select jsonb_agg(jsonb_build_object('leave_date',pl.leave_date,'status',pl.status)
      order by pl.leave_date)::text from public.paid_leave_requests pl
      where pl.company_id=cid and pl.worker_id=wid and pl.leave_date between start_day and end_day
        and pl.leave_date<=(current_timestamp at time zone 'Asia/Tokyo')::date),'')||
    coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'site_id',scsp.site_id,'source',scsp.source,
          'trade_company_id',scsp.trade_company_id,
          'contract',to_jsonb(ct)-'updated_at'
        )
        order by scsp.site_id
      )::text
      from public.site_calculation_source_preferences scsp
      left join public.trade_company_contracts ct
        on ct.company_id=scsp.company_id and ct.trade_company_id=scsp.trade_company_id
      where scsp.company_id=cid and scsp.output_type='payroll'
    ),'')
  )
  into fingerprint;

  for a in
    select ae.*
    from public.attendance_entries ae
    where ae.company_id=cid and ae.worker_id=wid
      and ae.work_date between start_day and end_day
      and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date
    order by ae.work_date,ae.id
  loop
    count_rows:=count_rows+1;
    trade_amount:=0;
    pref:=null;

    select scsp.source,tc.id as trade_company_id,
           coalesce(ct.contract_method,'none') as contract_method,
           coalesce(ct.daily_rate_yen,0) as daily_rate_yen,
           coalesce(ct.monthly_rate_yen,0) as monthly_rate_yen,
           coalesce(ct.square_meter_unit_price_yen,0) as square_meter_unit_price_yen,
           coalesce(ct.square_meter_quantity,0) as square_meter_quantity,
           coalesce(ct.contract_amount_yen,0) as contract_amount_yen
    into pref
    from public.site_calculation_source_preferences scsp
    join public.trade_companies tc
      on tc.id=scsp.trade_company_id and tc.company_id=cid
    left join public.trade_company_contracts ct
      on ct.company_id=cid and ct.trade_company_id=tc.id
    where scsp.company_id=cid and scsp.site_id=a.site_id
      and scsp.output_type='payroll'
    limit 1;

    if pref.source='trade_company' then
      if pref.contract_method='daily' then
        trade_amount:=round(coalesce(a.base_man_days,0)*pref.daily_rate_yen);
      elsif pref.contract_method='monthly' then
        if not pref.trade_company_id=any(fixed_trade_seen) then
          fixed_trade_seen:=array_append(fixed_trade_seen,pref.trade_company_id);
          trade_amount:=pref.monthly_rate_yen;
        end if;
      elsif pref.contract_method='square_meter' then
        if not pref.trade_company_id=any(fixed_trade_seen) then
          fixed_trade_seen:=array_append(fixed_trade_seen,pref.trade_company_id);
          trade_amount:=round(pref.square_meter_quantity*pref.square_meter_unit_price_yen);
        end if;
      elsif pref.contract_method='contract' then
        if not pref.trade_company_id=any(fixed_trade_seen) then
          fixed_trade_seen:=array_append(fixed_trade_seen,pref.trade_company_id);
          trade_amount:=pref.contract_amount_yen;
        end if;
      end if;
      total:=total+trade_amount;
    else
      category:=coalesce(a.work_category,'day');
      total:=total
        + round(coalesce(a.base_man_days,0) * coalesce((settings->>(category||'_daily'))::numeric,0))
        + round(coalesce(a.overtime_hours,0) * coalesce((settings->>(category||'_overtime'))::numeric,0))
        + round(coalesce(a.early_hours,0) * coalesce((settings->>(category||'_early'))::numeric,0));
    end if;

    foreach allowance in array coalesce(a.allowance_names,'{}'::text[]) loop
      token:=a.work_date::text||':'||allowance;
      if token=any(seen) then continue; end if;
      seen:=array_append(seen,token);
      allowance_index:=null;
      if settings is not null then
        select min(i) into allowance_index
        from generate_series(1,3)i
        where nullif(trim(settings->>('allowance_name_'||i)),'')=allowance;
      end if;
      if allowance_index is not null then
        total:=total+round(coalesce((settings->>('allowance_'||allowance_index))::numeric,0));
      end if;
    end loop;
  end loop;

  select count(distinct pl.leave_date) into leave_days
  from public.paid_leave_requests pl
  where pl.company_id=cid and pl.worker_id=wid and pl.status='approved'
    and pl.leave_date between start_day and end_day
    and pl.leave_date<=(current_timestamp at time zone 'Asia/Tokyo')::date
    and not exists(select 1 from public.attendance_entries ae
      where ae.company_id=pl.company_id and ae.worker_id=pl.worker_id and ae.work_date=pl.leave_date
        and (coalesce(ae.base_man_days,0)>0 or coalesce(ae.overtime_hours,0)>0
          or coalesce(ae.early_hours,0)>0 or coalesce(ae.night_hours,0)>0));
  leave_daily:=private.paid_leave_daily_amount(settings);
  if coalesce(settings->>'pay_type','daily')<>'monthly' then
    leave_total:=leave_days*leave_daily;
    total:=total+leave_total;
  end if;

  -- A registered positive monthly salary is payable independently of attendance.
  -- Daily/hourly approved leave-only months use the configured wage contract.
  if count_rows=0 and leave_days=0 and not (coalesce(settings->>'pay_type','daily')='monthly'
    and coalesce((settings->>'monthly_salary_yen')::numeric,0)>0)
    and jsonb_array_length(coalesce(settings#>'{_unit_resolution,items}','[]'))=0 then
    if current_statement.id is not null and current_statement.workflow_state='draft' and current_statement.automatic_calculation then
      delete from public.payroll_statements where id=current_statement.id;
    end if;
    return;
  end if;

  if settings is not null then
    total:=total+round(coalesce((settings->>'family_monthly')::numeric,0))
      +round(coalesce((settings->>'transport_monthly')::numeric,0));
    select coalesce(sum(greatest(coalesce((item->>'amount_yen')::integer,0),0)),0)
    into v_custom_deductions
    from jsonb_array_elements(coalesce(settings->'custom_deductions','[]'::jsonb)) item
    where nullif(trim(item->>'name'),'') is not null;

    v_deductions:=round(coalesce((settings->>'income_tax_monthly')::numeric,0))
      +(resident_source->>'amount_yen')::integer
      +round(coalesce((settings->>'social_insurance_monthly')::numeric,0))
      +round(coalesce((settings->>'other_deduction_monthly')::numeric,0))
      +round(v_custom_deductions);
  end if;

  -- Timeline remains a direct tax source even before wage settings exist.
  if settings is null then v_deductions := (resident_source->>'amount_yen')::integer; end if;
  total:=greatest(coalesce(total,0),0);
  v_deductions:=greatest(coalesce(v_deductions,0),0);
  -- Compare the same final amounts that the existing normalization triggers persist.
  -- INSERT/UPDATE below still provide raw attendance totals to those triggers.
  expected_gross:=total;
  if settings->>'pay_type'='monthly' then
    select coalesce(round(sum(coalesce(ae.base_man_days,0)
      *coalesce((settings->>'day_daily')::numeric,0))),0)
    into regular_day_base
    from public.attendance_entries ae
    where ae.company_id=cid and ae.worker_id=wid
      and ae.work_date between start_day and end_day
      and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date
      and coalesce(ae.work_category,'day')='day';
    expected_gross:=greatest(expected_gross-regular_day_base
      +round(coalesce((settings->>'monthly_salary_yen')::numeric,0)),0);
  end if;
  select coalesce(sum(greatest(coalesce((item->>'amount_yen')::integer,0),0)),0)
  into custom_earnings_total
  from jsonb_array_elements(coalesce(settings->'custom_earnings','[]'::jsonb)) item
  where nullif(trim(item->>'name'),'') is not null;
  expected_gross:=greatest(expected_gross+custom_earnings_total,0);
  tax_result:=payroll_tax_private.calculate(cid,wid,start_day,end_day,expected_gross::bigint,v_deductions::bigint);
  if tax_result is not null then
    v_deductions:=(tax_result->>'deductions')::numeric;
    fingerprint:=md5(fingerprint||tax_result::text);
  end if;
  expected_net:=greatest(expected_gross-v_deductions,0);
  -- Capture the calculation settings with the generated draft; history is not relabeled later.
  line_detail:=jsonb_build_object(
    'unit_resolution',settings->'_unit_resolution',
    'resident_tax_source',resident_source,
    'paid_leave_wage_contract',1,
    '有給単価',leave_daily,
    '有給支給額',leave_total,
    '有給内訳額',leave_days*leave_daily,
    'pay_type',coalesce(settings->>'pay_type','daily'),
    'rate_formula',coalesce(settings->'rate_formula','{}'::jsonb),
    'hourly_rate_yen',coalesce(settings->'hourly_rate_yen','0'::jsonb),
    '出勤日数',coalesce((select sum(coalesce(ae.base_man_days,0)) from public.attendance_entries ae
      where ae.company_id=cid and ae.worker_id=wid and ae.work_date between start_day and end_day
        and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date),0),
    '有給日数',coalesce((select count(*) from public.paid_leave_requests pl
      where pl.company_id=cid and pl.worker_id=wid and pl.leave_date between start_day and end_day
        and pl.leave_date<=(current_timestamp at time zone 'Asia/Tokyo')::date
        and pl.status='approved' and not exists (
      select 1 from public.attendance_entries ae where ae.company_id=pl.company_id
        and ae.worker_id=pl.worker_id and ae.work_date=pl.leave_date
        and (coalesce(ae.base_man_days,0)>0 or coalesce(ae.overtime_hours,0)>0
          or coalesce(ae.early_hours,0)>0 or coalesce(ae.night_hours,0)>0)
    )),0),
    '出勤に基づく支給額',greatest(total-v_deductions,0),
    '計算元選択あり',exists(
      select 1 from public.site_calculation_source_preferences scsp
      where scsp.company_id=cid and scsp.output_type='payroll'
        and scsp.source='trade_company'
        and exists(
          select 1 from public.attendance_entries ae
          where ae.company_id=cid and ae.worker_id=wid
            and ae.site_id=scsp.site_id
            and ae.work_date between start_day and end_day
            and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date
        )
    )
  );

  if current_statement.id is null then
    insert into public.payroll_statements(
      company_id,worker_id,period_start,period_end,gross_pay,deductions,net_pay,
      detail,workflow_state,approver_ids,automatic_calculation,calculation_blocked,calculation_fingerprint
    )
    values(
      cid,wid,start_day,end_day,total::int,v_deductions::int,greatest(total-v_deductions,0)::int,
      line_detail,'draft',private.payroll_approver_ids(cid),true,false,fingerprint
    )
    returning id,revision into saved_id,saved_revision;
  elsif current_statement.gross_pay is distinct from expected_gross::int
      or current_statement.deductions is distinct from v_deductions::int
      or current_statement.net_pay is distinct from expected_net::int
      or current_statement.calculation_fingerprint is distinct from fingerprint
      or current_statement.calculation_blocked is distinct from (coalesce((tax_result->>'blocked')::boolean,false) or coalesce((settings#>>'{_unit_resolution,blocked}')::boolean,false)) then
    update public.payroll_statements
    set gross_pay=total::int,
        deductions=v_deductions::int,
        net_pay=greatest(total-v_deductions,0)::int,
        detail=line_detail,
        calculation_fingerprint=fingerprint,
        calculation_blocked=false,
        approved_ids='{}',
        revision=revision+1,
        updated_at=now()
    where id=current_statement.id
    returning id,revision into saved_id,saved_revision;
  end if;

  if saved_id is not null then
    insert into public.payroll_audit(company_id,statement_id,revision,action,actor_id)
    values(cid,saved_id,saved_revision,'automatic_recalculation',auth.uid());
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.sign_daily_report(p_report_id uuid, p_signer_name text, p_signature_json jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare scope_before jsonb;
  v_user_id uuid:=auth.uid();
  v_company_id uuid;
  v_site_id uuid;
  v_route_id uuid;
  v_date date;
  v_detail record;
  v_entry_id uuid;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;

  if not exists(select 1 from public.daily_reports dr join public.company_members cm on cm.company_id=dr.company_id and cm.user_id=auth.uid() where dr.id=p_report_id) then raise exception 'daily report not found'; end if;
  scope_before:=payroll_scope_private.report_sources(p_report_id);
  perform payroll_scope_private.lock_scopes(scope_before->'scopes');
  select dr.company_id,dr.site_id,dr.route_assignment_id,dr.report_date
  into v_company_id,v_site_id,v_route_id,v_date
  from public.daily_reports dr
  join public.company_members cm
    on cm.company_id=dr.company_id and cm.user_id=v_user_id
  where dr.id=p_report_id
  for update;

  if v_company_id is null then raise exception 'daily report not found'; end if;
  perform 1 from public.daily_report_workers where report_id=p_report_id order by worker_id for share;
  if payroll_scope_private.report_sources(p_report_id) is distinct from scope_before then raise exception 'daily report payroll scope changed' using errcode='40001'; end if;

  if nullif(trim(coalesce(p_signer_name,'')),'') is null then
    raise exception 'signer name is required';
  end if;
  if p_signature_json is null or p_signature_json='[]'::jsonb then
    raise exception 'signature is required';
  end if;

  update public.daily_reports
  set status='signed',
      signer_name=trim(p_signer_name),
      signature_json=p_signature_json,
      signed_at=now(),
      updated_by=v_user_id,
      updated_at=now()
  where id=p_report_id;

  delete from public.attendance_entries ae
  where ae.source_report_id=p_report_id
    and (
      ae.site_id is distinct from v_site_id
      or ae.route_assignment_id is distinct from v_route_id
      or ae.work_date<>v_date
      or not exists(
        select 1 from public.daily_report_workers rw
        where rw.report_id=p_report_id and rw.worker_id=ae.worker_id
      )
    );

  for v_detail in
    select * from public.daily_report_workers
    where report_id=p_report_id
  loop
    select ae.id into v_entry_id
    from public.attendance_entries ae
    where ae.company_id=v_company_id
      and ae.worker_id=v_detail.worker_id
      and ae.site_id is not distinct from v_site_id
      and ae.route_assignment_id is not distinct from v_route_id
      and ae.work_date=v_date
      and ae.source_report_id=p_report_id
    order by ae.created_at
    limit 1;

    if v_entry_id is null then
      if exists(
        select 1 from public.attendance_entries ae
        where ae.company_id=v_company_id
          and ae.worker_id=v_detail.worker_id
          and ae.site_id is not distinct from v_site_id
          and ae.route_assignment_id is not distinct from v_route_id
          and ae.work_date=v_date
          and ae.source_report_id is distinct from p_report_id
      ) then
        raise exception '同じ日・勤務先の別の出勤記録があります。管理者が確認してください。';
      end if;

      insert into public.attendance_entries(
        company_id,work_date,worker_id,site_id,route_assignment_id,
        base_man_days,overtime_hours,early_hours,night_hours,
        allowance_amount,notes,work_category,allowance_names,
        source_report_id,created_by,updated_by
      )
      values(
        v_company_id,v_date,v_detail.worker_id,v_site_id,v_route_id,
        1,v_detail.overtime_hours,v_detail.early_hours,v_detail.night_hours,
        v_detail.allowance_amount,v_detail.allowance_label,v_detail.work_category,
        array(
          select distinct trim(v)
          from unnest(string_to_array(coalesce(v_detail.allowance_label,''),E'\n')) v
          where trim(v)<>''
        ),
        p_report_id,v_user_id,v_user_id
      );
    else
      update public.attendance_entries
      set base_man_days=1,
          overtime_hours=v_detail.overtime_hours,
          early_hours=v_detail.early_hours,
          night_hours=v_detail.night_hours,
          allowance_amount=v_detail.allowance_amount,
          notes=v_detail.allowance_label,
          work_category=v_detail.work_category,
          allowance_names=array(
            select distinct trim(v)
            from unnest(string_to_array(coalesce(v_detail.allowance_label,''),E'\n')) v
            where trim(v)<>''
          ),
          source_report_id=p_report_id,
          updated_by=v_user_id,
          updated_at=now()
      where id=v_entry_id and source_report_id=p_report_id;
    end if;

    v_entry_id:=null;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION payroll_unit_private.resolve_company_common(cid uuid, wid uuid, p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare item jsonb; publication company_common_allowance_private.payroll_publications%rowtype;
 legacy_result jsonb;raw jsonb;typ text;quantity numeric;amount numeric;rows jsonb:='[]';earnings jsonb:='[]';deductions jsonb:='[]';blocked boolean:=false;
begin
 if p_start is null or p_end is null or p_start<>date_trunc('month',p_start)::date
 or p_end<>(p_start+interval '1 month - 1 day')::date then
  raise exception 'canonical payroll month required' using errcode='22023';end if;
 if not exists(select 1 from company_common_allowance_private.payroll_activation a where a.company_id=cid and a.starts_on<=p_start) then
  return jsonb_build_object('items',rows,'earnings',earnings,'deductions',deductions,'blocked',false,'history_missing',false);end if;
 select s.pay_type into typ from public.worker_payroll_settings s join public.workers w on w.company_id=s.company_id and w.id=s.worker_id where s.company_id=cid and s.worker_id=wid;
 if exists(select 1 from company_common_allowance_private.payroll_activation_modes m where m.company_id=cid and m.mode='per_type')
 and not exists(select 1 from company_common_allowance_private.payroll_type_activation a where a.company_id=cid and a.payroll_type=typ and a.starts_on<=p_start) then
  return jsonb_build_object('items',rows,'earnings',earnings,'deductions',deductions,'blocked',false,'history_missing',false);end if;
 select * into publication from company_common_allowance_private.payroll_publications p
  where p.company_id=cid and p.payroll_type=typ and p.starts_on<=p_start order by p.starts_on desc,p.version desc limit 1;
 if not found then
  return jsonb_build_object('items',rows,'earnings',earnings,'deductions',deductions,'blocked',true,'history_missing',true);end if;
 if exists(select 1 from jsonb_array_elements(publication.items) e where e->>'origin'='company_legacy') then
  legacy_result:=company_common_canonical_review_private.resolve_legacy(cid,wid,p_start,p_end,publication.items,publication.version,publication.starts_on);
  rows:=legacy_result->'items';earnings:=legacy_result->'earnings';blocked:=(legacy_result->>'blocked')::boolean;
 else legacy_result:=null;end if;
 for item in select value from jsonb_array_elements(publication.items) where value->>'origin' is distinct from 'company_legacy' loop
  quantity:=null;amount:=null;
  if item->>'unit'='month' then quantity:=1;
  elsif item->>'unit'='day' then
   select count(distinct ae.work_date) into quantity from public.attendance_entries ae
    where ae.company_id=cid and ae.worker_id=wid and ae.work_date between p_start and p_end
     and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date and ae.base_man_days>0;
  elsif item->>'unit'='hour' then
   select q.hours into quantity from payroll_unit_private.quantities q
    where q.company_id=cid and q.worker_id=wid and q.item_id=(item->>'id')::uuid and q.month=p_start;
  end if;
  if quantity is null then blocked:=true;
  else
   amount:=round((item->>'amount_yen')::numeric*quantity);
   if amount>2147483647 then raise exception 'company common amount exceeds range' using errcode='22023';end if;
   if item->>'section'='earning' then earnings:=earnings||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));
   else deductions:=deductions||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));end if;
  end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',item->>'id','origin','company_common',
   'payroll_type',typ,'section',item->>'section','unit',item->>'unit','name',item->>'name',
   'rate_yen',item->'amount_yen','quantity',quantity,'quantity_month',p_start,'amount_yen',amount,
   'publication_version',publication.version,'starts_on',publication.starts_on));
 end loop;
 return jsonb_build_object('items',rows,'earnings',earnings,'deductions',deductions,'blocked',blocked,
  'history_missing',false,'publication_version',publication.version,'starts_on',publication.starts_on)||case when legacy_result is null then '{}'::jsonb else jsonb_build_object('legacy_resolution',legacy_result-'effective_settings','effective_settings',legacy_result->'effective_settings') end;
end $function$

CREATE OR REPLACE FUNCTION payroll_unit_private.augment_settings(cid uuid, wid uuid, p_start date, p_end date, settings jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare resolved jsonb;common_items jsonb;effective jsonb:=settings;raw jsonb;
begin
 resolved:=payroll_unit_private.resolve(cid,wid,p_start,p_end);
 common_items:=payroll_unit_private.resolve_company_common(cid,wid,p_start,p_end);
 if jsonb_typeof(common_items->'effective_settings')='object' then
  select to_jsonb(s) into raw from public.worker_payroll_settings s where s.company_id=cid and s.worker_id=wid;
  if raw is distinct from settings then raise exception 'fresh canonical worker settings required' using errcode='40001';end if;
  effective:=common_items->'effective_settings';
 end if;
 resolved:=resolved||jsonb_build_object('items',(resolved->'items')||(common_items->'items'),
  'earnings',(resolved->'earnings')||(common_items->'earnings'),'deductions',(resolved->'deductions')||(common_items->'deductions'),
  'blocked',(resolved->>'blocked')::boolean or (common_items->>'blocked')::boolean,
  'company_common_history_missing',common_items->'history_missing');
 if common_items->'legacy_resolution' is not null then
  resolved:=resolved||jsonb_build_object('company_common_resolution',jsonb_build_object('blocked',common_items->'blocked','reasons',common_items#>'{legacy_resolution,reasons}','selection_classification',common_items#>'{legacy_resolution,selection_classification}'));
 end if;
 if resolved->'items'='[]'::jsonb and (resolved->>'blocked')::boolean is not true then return effective;end if;
 return coalesce(effective,'{}')||jsonb_build_object('custom_earnings',coalesce(effective->'custom_earnings','[]')||(resolved->'earnings'),
 'custom_deductions',coalesce(effective->'custom_deductions','[]')||(resolved->'deductions'),'_unit_resolution',resolved);
end $function$

CREATE OR REPLACE FUNCTION company_common_canonical_review_private.resolve_legacy(cid uuid, wid uuid, p_start date, p_end date, publication_items jsonb, p_version bigint, p_effective date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare raw jsonb;effective jsonb;item jsonb;slots integer[];slot integer;quantity numeric;amount numeric;individual_items jsonb;
 rows jsonb:='[]';earnings jsonb:='[]';reasons jsonb:='[]';catalog jsonb;classification jsonb:='[]';selection record;sources jsonb;paired boolean;state text;
begin
 select to_jsonb(s) into raw from public.worker_payroll_settings s join public.workers w on w.id=s.worker_id and w.company_id=s.company_id where s.company_id=cid and s.worker_id=wid;
 if raw is null then return jsonb_build_object('items',rows,'earnings',earnings,'blocked',true,'reasons',jsonb_build_array(jsonb_build_object('code','worker_scope_missing')));end if;
 effective:=raw;
 if exists(select 1 from jsonb_array_elements(publication_items) e group by e->>'id' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(publication_items) e group by btrim(e->>'name') having count(*)>1) then
 return jsonb_build_object('items',rows,'earnings',earnings,'blocked',true,'reasons',jsonb_build_array(jsonb_build_object('code','publication_source_collision')));end if;
 select c.items into individual_items from payroll_unit_private.conditions c where c.company_id=cid and c.worker_id=wid and c.starts_on<=p_start order by c.starts_on desc limit 1;
 select coalesce(jsonb_agg(source),'[]'::jsonb) into catalog from(
  select jsonb_build_object('kind',case when e->>'origin'='company_legacy' then 'company_legacy' else 'company_publication' end,'id',e->'id','name',e->'name','rate_yen',e->'amount_yen') source from jsonb_array_elements(publication_items) e
  union all select jsonb_build_object('kind','individual_legacy','slot',k,'name',btrim(raw->>('allowance_name_'||k)),'rate_yen',coalesce((raw->>('allowance_'||k))::numeric,0)) from generate_series(1,3) k where nullif(btrim(raw->>('allowance_name_'||k)),'') is not null
  union all select jsonb_build_object('kind','individual_unit','id',e->'id','name',e->'name') from jsonb_array_elements(coalesce(individual_items,'[]'::jsonb)) e
  union all select jsonb_build_object('kind','individual_custom','index',ord,'name',e->'name') from jsonb_array_elements(coalesce(raw->'custom_earnings','[]'::jsonb)) with ordinality x(e,ord)
 ) candidates;
 for selection in select distinct name from public.attendance_entries a cross join unnest(coalesce(a.allowance_names,'{}'::text[])) name where a.company_id=cid and a.worker_id=wid and a.work_date between p_start and p_end and a.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date order by name loop
  select coalesce(jsonb_agg(e order by e->>'kind',e::text),'[]'::jsonb) into sources from jsonb_array_elements(catalog) e where e->>'name'=selection.name;
  paired:=jsonb_array_length(sources)=2 and exists(select 1 from jsonb_array_elements(sources) p join jsonb_array_elements(sources) l on p->>'kind'='company_legacy' and l->>'kind'='individual_legacy' and p->'rate_yen'=l->'rate_yen');
  if sources='[]'::jsonb then state:='interpretation_unconfirmed';reasons:=reasons||jsonb_build_array(jsonb_build_object('code','attendance_interpretation_unconfirmed','name',selection.name));
  elsif jsonb_array_length(sources)>1 and not paired then state:='source_collision_unresolved';reasons:=reasons||jsonb_build_array(jsonb_build_object('code','attendance_source_collision','name',selection.name));
  else state:=case when paired then 'approved_same_rate_legacy_pair' else 'known_source' end;end if;
  classification:=classification||jsonb_build_array(jsonb_build_object('name',selection.name,'state',state,'sources',(select coalesce(jsonb_agg(e-'rate_yen'),'[]'::jsonb) from jsonb_array_elements(sources) e)));
 end loop;
 for item in select value from jsonb_array_elements(publication_items) where value->>'origin'='company_legacy' loop
  if item->>'quantity_basis' is distinct from 'attendance_selected_distinct_dates' or item->>'individual_reconciliation' is distinct from 'inherit_absent_or_same_rate_otherwise_unresolved'
   or item->'selection_aliases' is distinct from jsonb_build_array(item->>'name') or item->>'generation' is null or item->>'id' is null
   or (item->>'amount_yen')::numeric<=0 or (item->>'generation')::bigint<=0
   or item->>'section' is distinct from 'earning' or item->>'unit' is distinct from 'day' then
   reasons:=reasons||jsonb_build_array(jsonb_build_object('code','legacy_contract_unconfirmed','id',item->'id','name',item->'name'));continue;end if;
  if exists(select 1 from jsonb_array_elements(publication_items) e where e<>item and (e->>'id'=item->>'id' or btrim(e->>'name')=btrim(item->>'name'))) then
   reasons:=reasons||jsonb_build_array(jsonb_build_object('code','publication_source_collision','id',item->'id','name',item->'name'));continue;end if;
  select coalesce(array_agg(k order by k),'{}'::integer[]) into slots from generate_series(1,3) k where nullif(btrim(raw->>('allowance_name_'||k)),'')=item->>'name';
  if cardinality(slots)>1 then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','ambiguous_individual_name','id',item->'id','name',item->'name'));continue;end if;
  if cardinality(slots)=1 then slot:=slots[1];
   if coalesce((raw->>('allowance_'||slot))::numeric,0) is distinct from (item->>'amount_yen')::numeric then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','individual_override_unresolved','id',item->'id','name',item->'name'));continue;end if;
   effective:=jsonb_set(effective,array['allowance_'||slot],'0'::jsonb);
  end if;
  if exists(select 1 from jsonb_array_elements(coalesce(raw->'custom_earnings','[]'::jsonb)||coalesce(individual_items,'[]'::jsonb)) e where btrim(e->>'name')=btrim(item->>'name')) then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','individual_item_overlap_unresolved','id',item->'id','name',item->'name'));continue;end if;
  select count(distinct a.work_date) into quantity from public.attendance_entries a where a.company_id=cid and a.worker_id=wid and a.work_date between p_start and p_end and a.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date and item->>'name'=any(coalesce(a.allowance_names,'{}'::text[]));
  amount:=round((item->>'amount_yen')::numeric*quantity);
  if amount<0 or amount>2147483647 then raise exception 'canonical legacy amount exceeds range' using errcode='22023';end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('id',item->'id','generation',item->'generation','origin','company_common','source_origin','company_legacy','payroll_type',raw->>'pay_type','section','earning','unit','day','source_unit',item->'source_unit','quantity_basis',item->'quantity_basis','name',item->'name','rate_yen',item->'amount_yen','quantity',quantity,'quantity_month',p_start,'amount_yen',amount,'publication_version',p_version,'starts_on',p_effective,'inherited',true));
  earnings:=earnings||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));
 end loop;
 return jsonb_build_object('items',rows,'earnings',earnings,'blocked',reasons<>'[]'::jsonb,'reasons',reasons,'selection_classification',classification,'effective_settings',case when reasons='[]'::jsonb then effective else null end);
end $function$

CREATE OR REPLACE FUNCTION private.attendance_sync_payroll_detail()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform payroll_scope_private.lock_scopes((case when tg_op<>'INSERT' then jsonb_build_array(jsonb_build_object('cid',old.company_id,'wid',old.worker_id,'day',old.work_date)) else '[]'::jsonb end)||(case when tg_op<>'DELETE' then jsonb_build_array(jsonb_build_object('cid',new.company_id,'wid',new.worker_id,'day',new.work_date)) else '[]'::jsonb end),true);
  if tg_op <> 'INSERT' then
    perform private.sync_payroll_attendance_detail(old.company_id,old.worker_id,old.work_date);
  end if;
  if tg_op <> 'DELETE' then
    perform private.sync_payroll_attendance_detail(new.company_id,new.worker_id,new.work_date);
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_daily_report_draft(p_report_id uuid, p_site_id uuid, p_report_date date, p_work_description text, p_workers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_company_id uuid;
  v_report_id uuid := p_report_id;
  v_report_status text;
  v_edit_request_id uuid;
  v_worker jsonb;
  v_worker_id uuid;
begin
  if v_user_id is null then
    raise exception 'authentication required';
  end if;

  select cm.company_id
  into v_company_id
  from public.company_members cm
  where cm.user_id = v_user_id
  limit 1;

  if v_company_id is null then
    raise exception 'company membership not found';
  end if;

  if not exists (
    select 1 from public.sites s
    where s.id = p_site_id
      and s.company_id = v_company_id
  ) then
    raise exception 'site does not belong to company';
  end if;

  if v_report_id is not null then
    select dr.status
    into v_report_status
    from public.daily_reports dr
    where dr.id = v_report_id
      and dr.company_id = v_company_id
    for update;

    if not found then
      raise exception 'daily report not found';
    end if;

    if v_report_status = 'signed' then
      select req.id
      into v_edit_request_id
      from public.daily_report_edit_requests req
      where req.report_id = v_report_id
        and req.requested_by = v_user_id
        and req.status = 'approved'
      order by req.created_at desc
      limit 1
      for update;

      if v_edit_request_id is null then
        raise exception 'signed report requires approved edit request';
      end if;

      update public.daily_report_edit_requests
      set status = 'used',
          resolved_at = coalesce(resolved_at, now())
      where id = v_edit_request_id;
    end if;

    update public.daily_reports
    set site_id = p_site_id,
        report_date = p_report_date,
        work_description = p_work_description,
        status = 'draft',
        signer_name = null,
        signature_json = null,
        signed_at = null,
        updated_by = v_user_id,
        updated_at = now()
    where id = v_report_id;
  else
    insert into public.daily_reports(
      company_id,
      site_id,
      report_date,
      work_description,
      status,
      created_by,
      updated_by
    )
    values(
      v_company_id,
      p_site_id,
      p_report_date,
      p_work_description,
      'draft',
      v_user_id,
      v_user_id
    )
    on conflict(company_id, site_id, report_date) do update
    set work_description = excluded.work_description,
        updated_by = v_user_id,
        updated_at = now()
    returning id, status into v_report_id, v_report_status;

    if v_report_status = 'signed' then
      raise exception 'signed report requires edit approval';
    end if;
  end if;

  delete from public.daily_report_workers
  where report_id = v_report_id;

  for v_worker in
    select value from jsonb_array_elements(coalesce(p_workers, '[]'::jsonb))
  loop
    v_worker_id := (v_worker ->> 'worker_id')::uuid;
    if nullif(v_worker->>'work_category','') is not null and
       v_worker->>'work_category' not in ('day','night','holiday','holiday_night') then
      raise exception 'invalid work category';
    end if;
    if (select count(distinct trim(v)) from unnest(string_to_array(coalesce(v_worker->>'allowance_label',''), E'\n')) v where trim(v)<>'') > 3 then
      raise exception 'maximum three daily allowances';
    end if;


    if not exists (
      select 1 from public.workers w
      where w.id = v_worker_id
        and w.company_id = v_company_id
    ) then
      raise exception 'worker does not belong to company';
    end if;

    insert into public.daily_report_workers(
      report_id,
      worker_id,
      overtime_hours,
      early_hours,
      night_hours,
      allowance_amount,
      allowance_label,
      work_category
    )
    values(
      v_report_id,
      v_worker_id,
      greatest(coalesce((v_worker ->> 'overtime_hours')::numeric, 0), 0),
      greatest(coalesce((v_worker ->> 'early_hours')::numeric, 0), 0),
      greatest(coalesce((v_worker ->> 'night_hours')::numeric, 0), 0),
      greatest(coalesce((v_worker ->> 'allowance_amount')::integer, 0), 0),
      nullif(trim(coalesce(v_worker ->> 'allowance_label', '')), ''),
      nullif(v_worker ->> 'work_category', '')
    );
  end loop;

  return v_report_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.save_daily_report_destination_draft(p_report_id uuid, p_site_id uuid, p_route_assignment_id uuid, p_report_date date, p_work_description text, p_workers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  v_user_id uuid:=auth.uid();
  v_company_id uuid;
  v_report_id uuid:=p_report_id;
  v_report_status text;
  v_edit_request_id uuid;
  v_worker jsonb;
  v_worker_id uuid;
begin
  if v_user_id is null then raise exception 'authentication required'; end if;

  select cm.company_id into v_company_id
  from public.company_members cm
  where cm.user_id=v_user_id
  limit 1;
  if v_company_id is null then raise exception 'company membership not found'; end if;

  if ((p_site_id is null) = (p_route_assignment_id is null)) then
    raise exception 'select exactly one workplace destination';
  end if;

  if p_site_id is not null and not exists(
    select 1 from public.sites s
    where s.id=p_site_id and s.company_id=v_company_id
  ) then
    raise exception 'site does not belong to company';
  end if;

  if p_route_assignment_id is not null and not exists(
    select 1 from public.route_assignments r
    where r.id=p_route_assignment_id
      and r.company_id=v_company_id
      and r.is_active=true
  ) then
    raise exception 'route does not belong to company';
  end if;

  if v_report_id is not null then
    select dr.status into v_report_status
    from public.daily_reports dr
    where dr.id=v_report_id and dr.company_id=v_company_id
    for update;
    if not found then raise exception 'daily report not found'; end if;

    if v_report_status='signed' then
      select req.id into v_edit_request_id
      from public.daily_report_edit_requests req
      where req.report_id=v_report_id
        and req.requested_by=v_user_id
        and req.status='approved'
      order by req.created_at desc
      limit 1
      for update;
      if v_edit_request_id is null then
        raise exception 'signed report requires approved edit request';
      end if;
      update public.daily_report_edit_requests
      set status='used',resolved_at=coalesce(resolved_at,now())
      where id=v_edit_request_id;
    end if;

    update public.daily_reports
    set site_id=p_site_id,
        route_assignment_id=p_route_assignment_id,
        report_date=p_report_date,
        work_description=p_work_description,
        status='draft',
        signer_name=null,
        signature_json=null,
        signed_at=null,
        representative_signature_json=null,
        representative_signer_name=null,
        supervisor_signature_json=null,
        supervisor_signer_name=null,
        updated_by=v_user_id,
        updated_at=now()
    where id=v_report_id;
  else
    select dr.id,dr.status
    into v_report_id,v_report_status
    from public.daily_reports dr
    where dr.company_id=v_company_id
      and dr.report_date=p_report_date
      and dr.site_id is not distinct from p_site_id
      and dr.route_assignment_id is not distinct from p_route_assignment_id
    limit 1
    for update;

    if v_report_id is not null then
      if v_report_status='signed' then
        raise exception 'signed report requires edit approval';
      end if;
      update public.daily_reports
      set work_description=p_work_description,
          updated_by=v_user_id,
          updated_at=now()
      where id=v_report_id;
    else
      insert into public.daily_reports(
        company_id,site_id,route_assignment_id,report_date,
        work_description,status,created_by,updated_by
      )
      values(
        v_company_id,p_site_id,p_route_assignment_id,p_report_date,
        p_work_description,'draft',v_user_id,v_user_id
      )
      returning id into v_report_id;
    end if;
  end if;

  delete from public.daily_report_workers where report_id=v_report_id;

  for v_worker in
    select value from jsonb_array_elements(coalesce(p_workers,'[]'::jsonb))
  loop
    v_worker_id:=(v_worker->>'worker_id')::uuid;

    if nullif(v_worker->>'work_category','') is not null
       and v_worker->>'work_category' not in ('day','night','holiday','holiday_night')
    then
      raise exception 'invalid work category';
    end if;

    if (
      select count(distinct trim(v))
      from unnest(string_to_array(coalesce(v_worker->>'allowance_label',''),E'\n')) v
      where trim(v)<>''
    ) > 3 then
      raise exception 'maximum three daily allowances';
    end if;

    if not exists(
      select 1 from public.workers w
      where w.id=v_worker_id and w.company_id=v_company_id
    ) then
      raise exception 'worker does not belong to company';
    end if;

    insert into public.daily_report_workers(
      report_id,worker_id,overtime_hours,early_hours,night_hours,
      allowance_amount,allowance_label,work_category
    )
    values(
      v_report_id,v_worker_id,
      greatest(coalesce((v_worker->>'overtime_hours')::numeric,0),0),
      greatest(coalesce((v_worker->>'early_hours')::numeric,0),0),
      greatest(coalesce((v_worker->>'night_hours')::numeric,0),0),
      greatest(coalesce((v_worker->>'allowance_amount')::integer,0),0),
      nullif(trim(coalesce(v_worker->>'allowance_label','')),''),
      nullif(v_worker->>'work_category','')
    );
  end loop;

  return v_report_id;
end;
$function$

CREATE OR REPLACE FUNCTION private.attendance_refresh_payroll()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform payroll_scope_private.lock_scopes((case when tg_op<>'INSERT' then jsonb_build_array(jsonb_build_object('cid',old.company_id,'wid',old.worker_id,'day',old.work_date)) else '[]'::jsonb end)||(case when tg_op<>'DELETE' then jsonb_build_array(jsonb_build_object('cid',new.company_id,'wid',new.worker_id,'day',new.work_date)) else '[]'::jsonb end),true);
 if tg_op<>'INSERT' then perform private.refresh_automatic_payroll(old.company_id,old.worker_id,old.work_date); end if;
 if tg_op<>'DELETE' then perform private.refresh_automatic_payroll(new.company_id,new.worker_id,new.work_date); end if;
 return null;
end;
$function$

CREATE OR REPLACE FUNCTION private.save_daily_report_signature(p_report_id uuid, p_role text, p_signer_name text, p_signature_json jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare scope_before jsonb; r public.daily_reports%rowtype;
begin
  if auth.uid() is null then raise exception 'authentication required'; end if;
  if not exists(select 1 from public.daily_reports dr join public.company_members cm on cm.company_id=dr.company_id and cm.user_id=auth.uid() where dr.id=p_report_id) then raise exception 'daily report not found'; end if;
  scope_before:=payroll_scope_private.report_sources(p_report_id);
  perform payroll_scope_private.lock_scopes(scope_before->'scopes');
  select dr.* into r from public.daily_reports dr where dr.id=p_report_id and exists (
    select 1 from public.company_members cm where cm.company_id=dr.company_id and cm.user_id=auth.uid()
  ) for update;
  if r.id is null then raise exception 'daily report not found'; end if;
  perform 1 from public.daily_report_workers where report_id=p_report_id order by worker_id for share;
  if payroll_scope_private.report_sources(p_report_id) is distinct from scope_before then raise exception 'daily report payroll scope changed' using errcode='40001'; end if;

  if r.status <> 'draft' then raise exception 'signed report requires approved edit request'; end if;
  if p_role not in ('representative','supervisor') or p_role is null then raise exception 'invalid signature role'; end if;
  if nullif(trim(p_signer_name),'') is null then raise exception 'signer name is required'; end if;
  if jsonb_typeof(p_signature_json->'strokes') is distinct from 'array' then raise exception 'signature strokes required'; end if;
  if not exists (select 1 from jsonb_array_elements(p_signature_json->'strokes') stroke where jsonb_typeof(stroke)='array' and jsonb_array_length(stroke)>0) then raise exception 'signature strokes required'; end if;
  if p_role='representative' then
    update public.daily_reports set representative_signature_json=p_signature_json, representative_signer_name=trim(p_signer_name), updated_by=auth.uid(),updated_at=now() where id=p_report_id;
  else
    update public.daily_reports set supervisor_signature_json=p_signature_json, supervisor_signer_name=trim(p_signer_name),updated_by=auth.uid(),updated_at=now() where id=p_report_id;
  end if;
  select * into r from public.daily_reports where id=p_report_id;
  if r.representative_signature_json is not null and r.supervisor_signature_json is not null then
    -- Retain the existing finalization/attendance workflow, with two distinct signatures in the legacy envelope.
    perform public.sign_daily_report(p_report_id,r.supervisor_signer_name,jsonb_build_object('version',3,
      'representative',r.representative_signature_json,'supervisor',r.supervisor_signature_json));
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION payroll_unit_private.resolve(cid uuid, wid uuid, p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare config payroll_unit_private.conditions%rowtype; item jsonb; quantity numeric; amount numeric;
 rows jsonb:='[]'; earnings jsonb:='[]'; deductions jsonb:='[]'; blocked boolean:=false; v_days numeric;
begin
 if p_start<>date_trunc('month',p_start)::date or p_end<>(p_start+interval '1 month - 1 day')::date then
  raise exception 'canonical payroll month required' using errcode='22023';end if;
 select * into config from payroll_unit_private.conditions where company_id=cid and worker_id=wid
 and starts_on<=p_start order by starts_on desc limit 1;
 if not found then return jsonb_build_object('contract_version',1,'items',rows,'earnings',earnings,'deductions',deductions,'blocked',false);end if;
 for item in select value from jsonb_array_elements(config.items) loop
  quantity:=null;amount:=null;
  if item->>'unit'='month' then quantity:=1;
  elsif item->>'unit'='day' then
   select count(distinct ae.work_date) into quantity from public.attendance_entries ae
   where ae.company_id=cid and ae.worker_id=wid and ae.work_date between p_start and p_end
    and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date and ae.base_man_days>0;
  elsif item->>'source'='manual_hours' then
   select q.hours into quantity from payroll_unit_private.quantities q where q.company_id=cid
    and q.worker_id=wid and q.item_id=(item->>'id')::uuid and q.month=p_start;
  else
   -- Only explicitly recorded component hours; normal hours are never inferred from man-days.
   select case when count(*)=0 then 0
    when count(*) filter(where (to_jsonb(ae)->>(item->>'source')) is null)>0 then null
    else sum((to_jsonb(ae)->>(item->>'source'))::numeric) end into quantity
   from public.attendance_entries ae where ae.company_id=cid and ae.worker_id=wid
    and ae.work_date between p_start and p_end and ae.work_date<=(current_timestamp at time zone 'Asia/Tokyo')::date;
  end if;
  if quantity is null or quantity<0 then blocked:=true;
  else amount:=round((item->>'rate_yen')::numeric*quantity);
   if amount>2147483647 then raise exception 'payroll item amount exceeds range' using errcode='22023';end if;
   if item->>'section'='earning' then earnings:=earnings||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));
   else deductions:=deductions||jsonb_build_array(jsonb_build_object('name',item->>'name','amount_yen',amount));end if;
  end if;
  rows:=rows||jsonb_build_array(item||jsonb_build_object('quantity',quantity,'amount_yen',amount,'quantity_month',p_start));
 end loop;
 return jsonb_build_object('contract_version',1,'condition_version',config.version,'starts_on',config.starts_on,
 'items',rows,'earnings',earnings,'deductions',deductions,'blocked',blocked);
end $function$
